class MainActivity:ComponentActivity(){
    private lateinit var root:LinearLayout
    private lateinit var body:LinearLayout
    private lateinit var scroll:ScrollView
    private lateinit var title:TextView
    private lateinit var subtitle:TextView
    private lateinit var cfg:Connection
    private lateinit var api:Api
    private var generation=0
    private var back:(()->Unit)?=null
    private var currentMedia:MediaPlayerView?=null
    private var pollJob:Job?=null
    private var activeTab="Chats"
    private var refreshPage:(()->Unit)?=null
    private var lastStatus:JSONObject?=null
    private var statusPanel:LinearLayout?=null
    private val green=Color.rgb(0,128,105)
    private val ink=Color.rgb(17,27,33)
    private val muted=Color.rgb(102,119,129)
    override fun onCreate(state:Bundle?){super.onCreate(state);cfg=Connection(this);api=Api(this)
        window.statusBarColor=Color.WHITE;window.navigationBarColor=Color.WHITE
        window.decorView.systemUiVisibility=View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR or View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR
        root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setBackgroundColor(Color.WHITE)}
        root.setOnApplyWindowInsetsListener { v,i->v.setPadding(i.systemWindowInsetLeft,i.systemWindowInsetTop,i.systemWindowInsetRight,i.systemWindowInsetBottom);i };setContentView(root)
        onBackPressedDispatcher.addCallback(this,object:OnBackPressedCallback(true){override fun handleOnBackPressed(){back?.invoke()?:finish()}})
        EngineService.prepare(this)
        if(getSharedPreferences("engine-controls",MODE_PRIVATE).getBoolean("enabled",true))runCatching{EngineService.start(this)}
        if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(arrayOf(android.Manifest.permission.POST_NOTIFICATIONS),32)
        ArchiveSync.schedule(this);showChats()
    }
    override fun onDestroy(){pollJob?.cancel();currentMedia?.stop();super.onDestroy()}
    private fun dp(n:Int)=(n*resources.displayMetrics.density).toInt()
    private fun text(value:String,size:Float=15f,bold:Boolean=false)=TextView(this).apply{text=value;textSize=size;setTextColor(ink);if(bold)setTypeface(typeface,Typeface.BOLD);setPadding(dp(2),dp(3),dp(2),dp(3))}
    private fun rounded(color:Int,radius:Int=16)=GradientDrawable().apply{setColor(color);cornerRadius=dp(radius).toFloat()}
    private fun button(label:String,action:()->Unit)=Button(this).apply{text=label;isAllCaps=false;textSize=14f;setTextColor(green);background=rounded(Color.rgb(231,245,239),12);minHeight=dp(44);minimumHeight=dp(44);setPadding(dp(14),dp(8),dp(14),dp(8));stateListAnimator=null;setOnClickListener{action()}}
    private fun icon(name:String,action:()->Unit)=FrameLayout(this).apply{contentDescription=name;isClickable=true;isFocusable=true;addView(ArchiveIcon(this@MainActivity,name,green),FrameLayout.LayoutParams(dp(24),dp(24),Gravity.CENTER));setOnClickListener{action()}}
    private fun card(parent:LinearLayout=body)=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(16),dp(14),dp(16),dp(14));background=rounded(Color.WHITE);parent.addView(this,LinearLayout.LayoutParams(-1,-2).apply{setMargins(dp(14),dp(6),dp(14),dp(6))})}
    private fun page(name:String,description:String="",onBack:(()->Unit)?=null){generation++;pollJob?.cancel();currentMedia?.stop();currentMedia=null;back=onBack;refreshPage=null;statusPanel=null;root.removeAllViews()
        val bar=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL;setPadding(dp(14),dp(4),dp(8),dp(4));setBackgroundColor(Color.WHITE)}
        if(onBack!=null)bar.addView(icon("Back"){onBack()},LinearLayout.LayoutParams(dp(40),dp(48)))
        val headings=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};title=text(name,if(onBack==null)27f else 18f,true).apply{if(name=="Whatsgramy")setTextColor(green)};subtitle=text(description,12f).apply{setTextColor(muted);visibility=if(description.isBlank())View.GONE else View.VISIBLE};headings.addView(title);headings.addView(subtitle);bar.addView(headings,LinearLayout.LayoutParams(0,-2,1f));bar.addView(icon("Refresh"){if(refreshPage!=null){refreshPage?.invoke()}else when(activeTab){"Files"->showFiles();"Settings"->showSettings();else->showChats()}},LinearLayout.LayoutParams(dp(44),dp(48)));root.addView(bar,LinearLayout.LayoutParams(-1,dp(if(description.isBlank())60 else 68)))
        scroll=ScrollView(this).apply{isFillViewport=true;clipToPadding=false};body=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(0,0,0,dp(14));setBackgroundColor(if(activeTab=="Settings")Color.rgb(246,248,247)else Color.WHITE)};scroll.addView(body);root.addView(scroll,LinearLayout.LayoutParams(-1,0,1f))
        if(onBack==null){val nav=LinearLayout(this).apply{gravity=Gravity.CENTER;setPadding(dp(6),dp(6),dp(6),dp(6));setBackgroundColor(Color.WHITE)}
            listOf("Chats","Files","Transfers","Settings").forEach{tab->val item=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER;contentDescription=tab;setOnClickListener{when(tab){"Chats"->showChats();"Files"->showFiles();"Transfers"->showHistory();else->showSettings()}}};val pill=FrameLayout(this).apply{if(activeTab==tab)background=rounded(Color.rgb(217,253,211),24);addView(ArchiveIcon(this@MainActivity,tab,if(activeTab==tab)green else muted),FrameLayout.LayoutParams(dp(24),dp(24),Gravity.CENTER))};item.addView(pill,LinearLayout.LayoutParams(dp(62),dp(30)));item.addView(text(tab,12f,activeTab==tab));nav.addView(item,LinearLayout.LayoutParams(0,dp(58),1f))};root.addView(nav)}
    }
    private fun runWork(action:suspend()->Unit){val g=generation;lifecycleScope.launch{try{action()}catch(e:CancellationException){throw e}catch(e:Exception){if(g==generation)AlertDialog.Builder(this@MainActivity).setTitle("Couldn't complete that").setMessage(e.message?:"Try again when the archive is connected.").setPositiveButton("OK",null).show()}}}
    private suspend fun request(path:String,method:String="GET",body:JSONObject?=null,query:Map<String,String> = emptyMap())=withContext(Dispatchers.IO){api.json(path,method,body,query)}
    private fun formatSize(n:Long)=when{n>=1_000_000_000->"%.1f GB".format(n/1e9);n>=1_000_000->"%.1f MB".format(n/1e6);n>=1000->"%.0f KB".format(n/1e3);else->"$n B"}
    private fun jsonItems(j:JSONObject)=j.optJSONArray("items")?:JSONArray()
    private fun JSONArray.rows()=(0 until length()).map{getJSONObject(it)}
    private fun str(j:JSONObject,key:String,fallback:String="")=j.optString(key).takeUnless{it=="null"||it.isBlank()}?:fallback
    private fun time(value:Long)=if(value>0)SimpleDateFormat("HH:mm",Locale.getDefault()).format(Date(value))else ""
    private fun date(value:Long)=if(value>0)DateFormat.getDateInstance(DateFormat.MEDIUM).format(Date(value))else ""
    private fun cacheKey(path:String,query:Map<String,String>)=MessageDigest.getInstance("SHA-256").digest((path+query.toSortedMap().toString()).toByteArray()).joinToString(""){"%02x".format(it)}
    private fun cacheFile(path:String,query:Map<String,String>)=File(filesDir,"archive-view/${cacheKey(path,query)}.json")
    private fun cached(path:String,query:Map<String,String>)=runCatching{JSONObject(cacheFile(path,query).readText())}.getOrNull()
    private fun remember(path:String,query:Map<String,String>,j:JSONObject){runCatching{val f=cacheFile(path,query);f.parentFile?.mkdirs();f.writeText(j.toString())}}
    private fun connectionLine()=text("Connecting to your archive…",12f).apply{setTextColor(muted);setPadding(dp(20),dp(6),dp(20),dp(8));body.addView(this)}
    private fun live(path:String,query:Map<String,String>,line:TextView,render:(JSONObject)->Unit){val g=generation;var previous="";cached(path,query)?.let{render(it);previous=it.toString();line.text="Showing the last loaded archive · reconnecting"}
        pollJob=lifecycleScope.launch{var first=true;while(isActive&&g==generation){try{val result=request(path,query=query);remember(path,query,result);statusPanel?.let{target->try{val state=request("/api/status");target.removeAllViews();statusSummary(target,state)}catch(e:CancellationException){throw e}catch(_:Exception){}};val signature=result.toString()+MediaCache(this@MainActivity).use{it.fileCount().toString()};if(signature!=previous){render(result);previous=signature};line.text="Live · updated ${time(System.currentTimeMillis())}";line.setTextColor(green);first=false}catch(e:CancellationException){throw e}catch(e:Exception){line.text=if(first&&previous.isEmpty())"Archive is starting or disconnected. Tap here to retry; Settings can resume it."else"Connection paused · showing last loaded data · tap to retry";line.setTextColor(Color.rgb(158,101,31));line.setOnClickListener{runCatching{EngineService.start(this@MainActivity)}}};delay(2500)}}
    }
    private fun searchBox(hintText:String,value:String,search:(String)->Unit){val edit=EditText(this).apply{hint=hintText;setText(value);textSize=15f;setSingleLine();setPadding(dp(20),dp(10),dp(16),dp(10));background=rounded(Color.rgb(242,244,245),28);imeOptions=android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH;setOnEditorActionListener{_,_,_->search(text.toString());true}};body.addView(edit,LinearLayout.LayoutParams(-1,dp(48)).apply{setMargins(dp(16),dp(4),dp(16),dp(10))})}
    private fun chips(labels:List<String>,selected:String,select:(String)->Unit){val strip=HorizontalScrollView(this).apply{isHorizontalScrollBarEnabled=false};val row=LinearLayout(this).apply{setPadding(dp(16),dp(2),dp(12),dp(10))};labels.forEach{label->row.addView(text(label,13f,true).apply{setPadding(dp(15),dp(8),dp(15),dp(8));background=rounded(if(label==selected)Color.rgb(217,253,211)else Color.rgb(243,245,246),24);setTextColor(if(label==selected)green else muted);setOnClickListener{select(label)}},LinearLayout.LayoutParams(-2,-2).apply{rightMargin=dp(8)})};strip.addView(row);body.addView(strip)}
    private fun avatar(name:String,size:Int=52)=TextView(this).apply{text=name.trim().split(" ").filter{it.isNotBlank()}.take(2).joinToString(""){it.take(1)}.uppercase().ifBlank{"?"};textSize=(size/3).toFloat();gravity=Gravity.CENTER;setTextColor(green);background=rounded(Color.rgb(225,240,234),size);typeface=Typeface.DEFAULT_BOLD}
    private fun empty(parent:LinearLayout,heading:String,detail:String,action:(()->Unit)?=null){val c=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER;setPadding(dp(30),dp(36),dp(30),dp(36))};c.addView(ArchiveIcon(this,"Files",green),LinearLayout.LayoutParams(dp(42),dp(42)));c.addView(text(heading,18f,true).apply{gravity=Gravity.CENTER});c.addView(text(detail,14f).apply{gravity=Gravity.CENTER;setTextColor(muted)});if(action!=null)c.addView(button("Open Settings",action));parent.addView(c)}
    private fun statusSummary(parent:LinearLayout,j:JSONObject){val stats=j.optJSONObject("stats")?:JSONObject();lastStatus=j;val s=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(14),dp(10),dp(14),dp(10));background=rounded(Color.rgb(238,248,242),14)};parent.addView(s,LinearLayout.LayoutParams(-1,-2).apply{setMargins(dp(16),dp(4),dp(16),dp(8))})
        val phoneCount=stats.optInt("local_files")+MediaCache(this).use{cache->cache.availableIds().count{id->!File(filesDir,"engine/media/$id").isFile}};s.addView(text("${stats.optInt("verified")} saved to Telegram   ·   $phoneCount on this phone",13f,true));val wa=j.optJSONObject("whatsapp")?.optString("connection");val tg=j.optJSONObject("telegram")?.optBoolean("connected")==true;val transfer=j.optJSONArray("transfers")?.rows()?.firstOrNull{it.optString("phase") in listOf("downloading","uploading","verifying")};val label=if(transfer!=null)"${str(transfer,"phase").replaceFirstChar{it.uppercase()}}: ${str(transfer,"name","Attachment")} ${if(transfer.isNull("percent"))""else"${transfer.optInt("percent")}%"}" else "${stats.optInt("pending")} waiting · ${stats.optInt("failed")} need attention · ${if(tg)"Telegram connected"else"Telegram offline"}";s.addView(text(label,12f).apply{setTextColor(muted)});if(wa!="open")s.addView(text("WhatsApp: ${wa?:"connecting"} · tap to manage connections",12f).apply{setTextColor(green)});s.setOnClickListener{showHistory()}}
    private fun showChats(query:String="",filter:String="All"){activeTab="Chats";page("Whatsgramy");searchBox("Search chats",query){showChats(it,filter)};chips(listOf("All","With files","Needs backup"),filter){showChats(query,it)};val line=connectionLine();statusPanel=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;body.addView(this)};val panel=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};body.addView(panel)
        live("/api/chats",emptyMap(),line){data->val y=scroll.scrollY;panel.removeAllViews();val rows=jsonItems(data).rows().filter{str(it,"title").contains(query,true)&&when(filter){"With files"->it.optInt("files")>0;"Needs backup"->it.optInt("files")>it.optInt("saved_files");else->true}}
            if(rows.isEmpty())empty(panel,"No chats to show",if(query.isNotBlank())"Try another name."else"Connect WhatsApp in Settings. Chats appear as your linked device syncs."){showSettings()}
            rows.forEach{c->val name=str(c,"title",str(c,"id"));val row=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL;setPadding(dp(16),dp(12),dp(16),dp(12));minimumHeight=dp(82);setOnClickListener{showChat(c.getString("id"),name)}};row.addView(avatar(name),LinearLayout.LayoutParams(dp(52),dp(52)).apply{rightMargin=dp(14)});val copy=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};val top=LinearLayout(this);top.addView(text(name,17f,true).apply{maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.END},LinearLayout.LayoutParams(0,-2,1f));top.addView(text(time(c.optLong("updated")),11f).apply{setTextColor(muted)});copy.addView(top);copy.addView(text(str(c,"preview",str(c,"last_file","No messages yet")),14f).apply{setTextColor(muted);maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.END});if(c.optInt("files")>0)copy.addView(text("${c.optInt("saved_files")} / ${c.optInt("files")} files saved to Telegram",11f).apply{setTextColor(green)});row.addView(copy,LinearLayout.LayoutParams(0,-2,1f));panel.addView(row);panel.addView(View(this).apply{setBackgroundColor(Color.rgb(241,243,244))},LinearLayout.LayoutParams(-1,dp(1)).apply{leftMargin=dp(82)})};scroll.post{scroll.scrollTo(0,y)}
        }
    }
    private fun showChat(id:String,name:String,before:Long=Long.MAX_VALUE,older:Boolean=false,beforeId:String=""){activeTab="Chats";page(name,"WhatsApp conversation · attachment archive",{showChats()});refreshPage={showChat(id,name,before,older,beforeId)};body.background=ChatWallpaper();val line=connectionLine();val panel=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(8),0,dp(8),dp(10))};body.addView(panel);var initial=true
        live("/api/messages",mapOf("chat" to id,"before" to before.toString(),"beforeId" to beforeId),line){data->val bottom=initial||scroll.getChildAt(0).height-scroll.height-scroll.scrollY<dp(180);val y=scroll.scrollY;panel.removeAllViews();val rows=jsonItems(data).rows();if(rows.size==100)panel.addView(button("Earlier messages"){val last=rows.last();showChat(id,name,last.getLong("timestamp"),true,last.getString("id"))});var day=""
            if(rows.isEmpty())empty(panel,"No messages here yet","New messages and attachment backups appear here automatically.")
            rows.asReversed().forEach{m->val d=date(m.optLong("timestamp"));if(d!=day){day=d;panel.addView(text(d,11f).apply{gravity=Gravity.CENTER;background=rounded(Color.rgb(255,255,255),10);setPadding(dp(12),dp(5),dp(12),dp(5))},LinearLayout.LayoutParams(-2,-2).apply{gravity=Gravity.CENTER_HORIZONTAL;setMargins(0,dp(12),0,dp(10))})};val outgoing=m.optInt("from_me")==1;val bubble=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(10),dp(6),dp(10),dp(5));background=rounded(if(outgoing)Color.rgb(217,253,211)else Color.WHITE,12);elevation=dp(1).toFloat()};panel.addView(bubble,LinearLayout.LayoutParams((resources.displayMetrics.widthPixels*0.82).toInt().coerceAtMost(dp(420)),-2).apply{gravity=if(outgoing)Gravity.END else Gravity.START;setMargins(if(outgoing)dp(30)else 0,dp(3),if(outgoing)0 else dp(30),dp(3))});if(id.endsWith("@g.us")&&!outgoing)bubble.addView(text(str(m,"sender"),12f,true).apply{setTextColor(green)});if(!m.isNull("media_id"))fileRow(bubble,m,true){showChat(id,name,before,older,beforeId)};if(str(m,"text").isNotBlank())bubble.addView(text(str(m,"text"),16f));bubble.addView(text(time(m.optLong("timestamp")),10f).apply{gravity=Gravity.END;setTextColor(muted)})};panel.addView(text("Files are opened here in Whatsgramy. This conversation is read-only.",11f).apply{setTextColor(muted);gravity=Gravity.CENTER;setPadding(dp(12),dp(18),dp(12),dp(8))});scroll.post{if(bottom&&!older)scroll.fullScroll(View.FOCUS_DOWN)else scroll.scrollTo(0,y)};initial=false}
    }
    private fun mediaId(m:JSONObject)=str(m,"media_id",m.optString("id"))
    private fun localFile(m:JSONObject):File? {val id=mediaId(m);if(!id.matches(Regex("[a-f0-9]{64}")))return null;return MediaCache(this).use{it.local(id)}?:File(filesDir,"engine/media/$id").takeIf{it.isFile}}
    private fun onPhone(m:JSONObject)=localFile(m)!=null
    private fun cloudSaved(m:JSONObject)=m.optBoolean("telegram_saved")||(m.optString("status")=="verified"&&m.optLong("telegram_id")>0)
    private fun phase(m:JSONObject):String=when(str(m,"status")){"verified"->"Saved to Telegram";"uploading"->"Uploading to Telegram";"uploaded","verifying"->"Uploaded · verifying backup";"downloading"->"Downloading from WhatsApp";"downloaded"->"On phone · waiting to upload";"failed"->"Backup failed · tap for details";"needs_source"->"Original file needed";else->"Waiting to download"}
    private fun fileRow(parent:LinearLayout,m:JSONObject,inChat:Boolean=false,refresh:()->Unit){val id=mediaId(m);val saved=cloudSaved(m);val local=onPhone(m);val block=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(10),dp(10),dp(10),dp(10));background=rounded(if(inChat)Color.argb(14,0,90,70)else Color.rgb(247,249,248),12)};parent.addView(block,LinearLayout.LayoutParams(-1,-2).apply{if(!inChat)setMargins(dp(16),dp(4),dp(16),dp(4))});val row=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL};val mime=str(m,"mime");val kind=if(mime.startsWith("image"))"Photo"else if(mime.startsWith("video"))"Video"else if(mime.startsWith("audio"))"Audio"else "Files";row.addView(ArchiveIcon(this,kind,if(saved)green else muted),LinearLayout.LayoutParams(dp(32),dp(38)).apply{rightMargin=dp(10)});val info=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};info.addView(text(str(m,"name","Attachment"),14f,true).apply{maxLines=2;ellipsize=android.text.TextUtils.TruncateAt.END});info.addView(text("${formatSize(m.optLong("size"))} · ${str(m,"name").substringAfterLast('.',kind).uppercase().take(8)}",11f).apply{setTextColor(muted)});row.addView(info,LinearLayout.LayoutParams(0,-2,1f));row.addView(icon(if(local)"Open"else if(saved)"Download"else"Info"){if(local||saved)open(m,refresh)else details(m)},LinearLayout.LayoutParams(dp(40),dp(42)));block.addView(row)
        if(mime.startsWith("image/")&&local){localFile(m)?.let{file->val image=ImageView(this).apply{scaleType=ImageView.ScaleType.CENTER_CROP;contentDescription=str(m,"name","Photo");setBackgroundColor(Color.rgb(226,235,230));setOnClickListener{open(m,refresh)}};block.addView(image,LinearLayout.LayoutParams(-1,dp(if(inChat)210 else 150)).apply{topMargin=dp(6);bottomMargin=dp(6)});val g=generation;lifecycleScope.launch{val bitmap=withContext(Dispatchers.IO){val o=BitmapFactory.Options().apply{inJustDecodeBounds=true};BitmapFactory.decodeFile(file.path,o);o.inSampleSize=maxOf(1,maxOf(o.outWidth,o.outHeight)/800);o.inJustDecodeBounds=false;BitmapFactory.decodeFile(file.path,o)};if(g==generation)image.setImageBitmap(bitmap)else bitmap?.recycle()}}}
        block.addView(text("${if(saved)"✓ "else ""}${phase(m)}",11f,true).apply{setTextColor(if(saved)green else if(str(m,"status")=="failed")Color.rgb(180,55,50)else muted)})
        block.addView(text(if(local)"✓ Available on this phone"else if(saved)"Not on phone · tap to download"else "Not downloaded on this phone",11f).apply{setTextColor(if(local)green else muted)})
        val transfer=m.optJSONObject("transfer");if(str(m,"status") in listOf("downloading","uploading","verifying")){val p=ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal).apply{max=100;isIndeterminate=transfer==null||transfer.isNull("percent")||str(m,"status")=="verifying";progress=transfer?.optInt("percent")?:0;progressTintList=android.content.res.ColorStateList.valueOf(green)};block.addView(p,LinearLayout.LayoutParams(-1,dp(5)));if(transfer!=null&&!transfer.isNull("percent"))block.addView(text("${transfer.optInt("percent")}% · ${formatSize(transfer.optLong("bytes"))} / ${formatSize(transfer.optLong("total"))}",10f))}
        block.setOnClickListener{if(local||saved)open(m,refresh)else details(m)};block.setOnLongClickListener{manage(m,refresh);true}
    }
    private fun details(m:JSONObject){val saved=cloudSaved(m);val message="${phase(m)}\n\nTelegram backup: ${if(saved)"Verified and saved"else if(m.optLong("telegram_id")>0)"Uploaded; verification pending"else"Not saved yet"}\nOn this phone: ${if(onPhone(m))"Yes"else"No"}\nSize: ${formatSize(m.optLong("size"))}\nUploaded: ${if(m.optLong("uploaded_at")>0)date(m.optLong("uploaded_at"))+" "+time(m.optLong("uploaded_at"))else"Not yet"}\n${str(m,"error")}\n\nSHA-256: ${str(m,"sha256","Not verified yet")}";AlertDialog.Builder(this).setTitle(str(m,"name","File details")).setMessage(message).setPositiveButton("OK",null).show()}
    private fun manage(m:JSONObject,refresh:()->Unit){val id=mediaId(m);val pinned=m.optInt("pinned")==1||MediaCache(this).use{it.pinned(id)};val choices=mutableListOf("File details");if(cloudSaved(m)){choices.add(if(pinned)"Allow automatic local cleanup"else"Keep on this phone");choices.add("Delete phone copies · keep Telegram backup")};if(str(m,"status")=="failed")choices.add("Retry backup");AlertDialog.Builder(this).setTitle(str(m,"name")).setItems(choices.toTypedArray()){_,which->when(choices[which]){"File details"->details(m);"Retry backup"->runWork{request("/api/media/$id/retry","POST");refresh()};"Keep on this phone","Allow automatic local cleanup"->runWork{request("/api/media/$id/pin","POST",JSONObject().put("pinned",!pinned));withContext(Dispatchers.IO){MediaCache(this@MainActivity).use{if(!pinned)it.ensure(m);it.pin(id,!pinned)}};refresh()};else->AlertDialog.Builder(this).setTitle("Delete local copies?").setMessage("The verified Telegram backup and this chat entry will stay. Tap the file later to download it again.").setNegativeButton("Cancel",null).setPositiveButton("Delete local"){_,_->runWork{request("/api/media/$id/delete-local","POST");withContext(Dispatchers.IO){MediaCache(this@MainActivity).use{it.delete(id)}};refresh()}}.show()}}.show()}
    private fun showFiles(query:String="",cursor:Long=0,filter:String="All"){activeTab="Files";page("Files");searchBox("Search filenames",query){showFiles(it,0,filter)};chips(listOf("All","On phone","Telegram","In progress","Failed"),filter){showFiles(query,0,it)};val line=connectionLine();val panel=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};body.addView(panel);live("/api/media",mapOf("q" to query,"cursor" to cursor.toString(),"limit" to "100"),line){data->val y=scroll.scrollY;panel.removeAllViews();val all=jsonItems(data).rows();val rows=all.filter{when(filter){"On phone"->onPhone(it);"Telegram"->cloudSaved(it);"In progress"->str(it,"status") !in listOf("verified","failed","needs_source");"Failed"->str(it,"status") in listOf("failed","needs_source");else->true}};panel.addView(text("${rows.size} files on this page · long-press to manage",11f).apply{setTextColor(muted);setPadding(dp(20),dp(4),dp(20),dp(8))});if(rows.isEmpty())empty(panel,"No ${if(filter=="All")"files"else filter.lowercase()+" files"} here",if(filter=="All")"New attachments appear here with their Telegram and phone status."else"Choose another filter, or check the next page.");rows.forEach{fileRow(panel,it){showFiles(query,cursor,filter)}};if(all.size==100)panel.addView(button("Next files"){showFiles(query,all.last().getLong("cursor"),filter)});scroll.post{scroll.scrollTo(0,y)}}}
    private fun showHistory(before:Long=Long.MAX_VALUE,beforeId:String=""){activeTab="Transfers";page("Transfers","Telegram backups and phone storage");val line=connectionLine();val summary=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};body.addView(summary);val panel=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};body.addView(panel)
        val g=generation;pollJob=lifecycleScope.launch{var signature="";while(isActive&&g==generation){try{val status=request("/api/status");val history=request("/api/history",query=mapOf("before" to before.toString(),"beforeId" to beforeId,"limit" to "60"));remember("/api/status",emptyMap(),status);remember("/api/history",emptyMap(),history);val next=status.toString()+history.toString();if(next!=signature){val y=scroll.scrollY;summary.removeAllViews();statusSummary(summary,status);panel.removeAllViews();val active=status.optJSONArray("transfers")?.rows().orEmpty();active.filter{it.optString("phase") in listOf("uploading","downloading","verifying")}.forEach{t->card(panel).addView(text("${str(t,"name")}\n${str(t,"phase")} · ${t.optInt("percent")}%",14f,true))};val events=jsonItems(history).rows();if(events.isEmpty())empty(panel,"No transfers yet","Receive an attachment in WhatsApp after connecting your accounts.");events.forEach{e->val row=LinearLayout(this@MainActivity).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(20),dp(12),dp(20),dp(12))};row.addView(text(str(e,"name","Archive activity"),14f,true));val label=when(str(e,"type")){"verified"->"✓ Saved to Telegram · verified";"uploading"->"Uploading to Telegram";"uploaded"->"Uploaded · awaiting verification";"downloaded"->"Downloaded on this phone";"local_removed"->"Removed from phone · Telegram copy kept";"retrieved_from_telegram"->"Downloaded back from Telegram";else->str(e,"type").replace('_',' ')};row.addView(text(label,12f).apply{setTextColor(if(e.optString("type")=="verified")green else muted)});row.addView(text("${date(e.optLong("timestamp"))} ${time(e.optLong("timestamp"))} · ${formatSize(e.optLong("bytes"))}",11f).apply{setTextColor(muted)});if(str(e,"detail").isNotBlank())row.addView(text(str(e,"detail"),12f));panel.addView(row)};if(events.size==60)panel.addView(button("Earlier transfers"){val e=events.last();showHistory(e.getLong("timestamp"),e.getString("id"))});signature=next;scroll.post{scroll.scrollTo(0,y)}};line.text="Live transfer activity · updated ${time(System.currentTimeMillis())}";line.setTextColor(green)}catch(e:CancellationException){throw e}catch(e:Exception){line.text="Can't connect to the archive · tap to resume";line.setOnClickListener{EngineService.start(this@MainActivity)};if(summary.childCount==0)cached("/api/status",emptyMap())?.let{statusSummary(summary,it)}};delay(2500)}}
    }
    private fun switch(parent:LinearLayout,label:String,detail:String,checked:Boolean,changed:(Boolean)->Unit){val sw=Switch(this).apply{text=label;textSize=15f;isChecked=checked;setTextColor(ink);setPadding(dp(2),dp(10),dp(2),dp(10));thumbTintList=android.content.res.ColorStateList(arrayOf(intArrayOf(android.R.attr.state_checked),intArrayOf()),intArrayOf(green,Color.LTGRAY));setOnCheckedChangeListener{_,v->changed(v)}};parent.addView(sw);if(detail.isNotBlank())parent.addView(text(detail,12f).apply{setTextColor(muted)})}
    private fun showSettings(){activeTab="Settings";page("Settings","Everything is under your control")
        val connect=card();connect.addView(text("On this phone",18f,true));connect.addView(text("WhatsApp, Telegram and your archive run inside this APK. No hosted server is needed.",14f))
        connect.addView(button("Start / resume archive engine"){EngineService.start(this);showSettings()})
        connect.addView(button("Stop archive engine"){getSharedPreferences("engine-controls",MODE_PRIVATE).edit().putBoolean("enabled",false).apply();stopService(android.content.Intent(this,EngineService::class.java));Toast.makeText(this,"Engine stopped. Resume here when needed.",Toast.LENGTH_LONG).show()})
        connect.addView(text("Android limits long-running background transfers. Keep the archive notification enabled and reopen Whatsgramy to resume if Android stops it. Never delete an original until its backup is verified.",12f))
        val phone=card();phone.addView(text("This phone",18f,true));switch(phone,"Download archived attachments automatically","Runs periodically while Android allows background work.",cfg.autoDownload){cfg.autoDownload=it;ArchiveSync.schedule(this)};switch(phone,"Wi-Fi only for automatic downloads","Manual opening can use your current connection.",cfg.wifiOnly){cfg.wifiOnly=it;ArchiveSync.schedule(this)};switch(phone,"Clean up this phone's local copies","Uses the archive retention period. Pinned copies are kept.",cfg.cleanup){cfg.cleanup=it}
        MediaCache(this).use{phone.addView(text("Local cache: ${it.fileCount()} files · ${formatSize(it.bytes())}\nFolder: ${it.folder()}",12f))}
        val engineState=text("Loading connections and backup controls…",13f);body.addView(engineState)
        val g=generation;runWork{val status=request("/api/status");if(g!=generation)return@runWork;engineState.text="Local engine ready · no hosted service needed"
            val accounts=card();accounts.addView(text("Connections",18f,true));val wa=status.getJSONObject("whatsapp");accounts.addView(text("WhatsApp: ${wa.optString("connection")}\nTelegram: ${if(status.getJSONObject("telegram").optBoolean("connected"))"connected"else"not connected"}"));if(!status.getJSONObject("telegram").optBoolean("connected"))telegramLogin(accounts)
            accounts.addView(button("Connect / refresh WhatsApp"){runWork{request("/api/whatsapp/start","POST");showSettings()}})
            val number=EditText(this).apply{hint="WhatsApp number with country code, digits only";inputType=InputType.TYPE_CLASS_PHONE};accounts.addView(number);accounts.addView(button("Get pairing code"){runWork{val response=request("/api/whatsapp/pair","POST",JSONObject().put("phone",number.text.toString().filter{it.isDigit()}));AlertDialog.Builder(this@MainActivity).setTitle("Link Whatsgramy").setMessage("In WhatsApp → Linked devices → Link a device → Link with phone number, enter:\n\n${response.getString("code")}").setPositiveButton("OK",null).show()}})
            val qr=wa.optString("qr");if(qr.startsWith("data:image")){val bytes=Base64.decode(qr.substringAfter(','),Base64.DEFAULT);accounts.addView(ImageView(this@MainActivity).apply{setImageBitmap(BitmapFactory.decodeByteArray(bytes,0,bytes.size));adjustViewBounds=true},LinearLayout.LayoutParams(-1,dp(260)));accounts.addView(text("Scan from WhatsApp → Linked devices using another screen, or use the pairing code above.",12f))}
            val settings=status.getJSONObject("settings");val archive=card();archive.addView(text("Archive controls",18f,true))
            val entries=listOf(Triple("enabled","Enable archive","Stops new archive transfers and automatic cleanup when off."),Triple("autoDownload","Capture WhatsApp attachments","Download available incoming attachments into the separate archive."),Triple("autoUpload","Upload to Telegram","Local files are retained until verification succeeds."),Triple("cloudOpen","Retrieve missing files from Telegram","Allow on-demand opening in Whatsgramy."),Triple("autoMetadata","Automatic recovery index backup","Save file references, counts, history and Settings to your Telegram Saved Messages."),Triple("autoCleanup","Automatic local cleanup","Only verified, indexed copies are eligible; originals in official WhatsApp are untouched."),Triple("photos","Photos",""),Triple("videos","Videos",""),Triple("audio","Audio and voice notes",""),Triple("documents","PDFs and documents",""),Triple("other","Other files and stickers",""))
            entries.forEach{(key,label,detail)->switch(archive,label,detail,settings.optBoolean(key)){value->runWork{try{request("/api/settings","PUT",JSONObject().put(key,value));ArchiveSync.schedule(this@MainActivity)}catch(e:Exception){showSettings();throw e}}}}
            val days=EditText(this@MainActivity).apply{hint="Retention days";inputType=InputType.TYPE_CLASS_NUMBER;setText(settings.optInt("retentionDays",15).toString())};archive.addView(days);archive.addView(button("Save retention period"){runWork{val n=days.text.toString().toIntOrNull()?:error("Enter 1–365 days");request("/api/settings","PUT",JSONObject().put("retentionDays",n));showSettings()}})
            val health=card();val stats=status.getJSONObject("stats");val metadata=status.optJSONObject("metadata")?:JSONObject();health.addView(text("Metadata recovery: ${metadata.optString("recovery_status","not checked")}\nLast index backup: ${if(metadata.optLong("last_backup_at",0)>0)DateFormat.getDateTimeInstance().format(Date(metadata.getLong("last_backup_at")))else "Not backed up yet"}",13f));if(!metadata.isNull("error")&&metadata.optString("error").isNotBlank())health.addView(text(metadata.optString("error"),12f));health.addView(text("${stats.optInt("uploaded")} uploaded · ${formatSize(stats.optLong("uploaded_bytes"))}\n${stats.optInt("pending")} pending · ${stats.optInt("needs_source")} need their original source",14f));val types=stats.optJSONObject("by_type")?:JSONObject();types.keys().forEach{kind->val type=types.getJSONObject(kind);health.addView(text("${kind.replaceFirstChar{it.uppercase()}}: ${type.optInt("verified")} verified / ${type.optInt("total")} · ${formatSize(type.optLong("bytes"))}",12f))};health.addView(button("View upload history"){showHistory()});health.addView(text("${stats.optInt("verified")} verified · ${stats.optInt("failed")} failed · ${stats.optInt("total")} attachments",15f,true));health.addView(button("Back up recovery index now"){runWork{request("/api/index/backup","POST");Toast.makeText(this@MainActivity,"Recovery index backed up",Toast.LENGTH_SHORT).show()}});health.addView(text("This is an unofficial linked-device archive. Account pairing and historical media depend on WhatsApp. View-once and disappearing messages are excluded. The app does not send chat messages.",12f))
        }
    }
    private fun telegramLogin(parent:LinearLayout){
        parent.addView(text("Connect Telegram",17f,true));parent.addView(text("Use your own API ID and API hash from my.telegram.org. Files and recovery indexes go to Saved Messages. Your session stays in this phone's private app storage.",12f))
        fun field(h:String,secret:Boolean=false)=EditText(this).apply{hint=h;setSingleLine();if(secret)inputType=InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_VARIATION_PASSWORD;parent.addView(this)}
        val id=field("Telegram API ID");id.inputType=InputType.TYPE_CLASS_NUMBER
        val hash=field("Telegram API hash",true);val number=field("Telegram phone, including country code");number.inputType=InputType.TYPE_CLASS_PHONE
        parent.addView(button("Sign in to Telegram"){runWork{request("/api/telegram/login","POST",JSONObject().put("apiId",id.text.toString()).put("apiHash",hash.text.toString()).put("phone",number.text.toString().trim()));waitTelegram()}})
        parent.addView(button("Continue Telegram sign-in"){runWork{waitTelegram()}})
    }
    private suspend fun waitTelegram(){
        for(attempt in 0 until 60){val result=request("/api/telegram/login");when(result.optString("state")){
            "code","password"->{val password=result.optString("state")=="password";val entry=EditText(this).apply{setSingleLine();inputType=if(password)InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_VARIATION_PASSWORD else InputType.TYPE_CLASS_NUMBER};AlertDialog.Builder(this).setTitle(if(password)"Telegram two-step password"else"Telegram login code").setMessage(result.optString("error").takeIf{it.isNotBlank()&&it!="null"}?:if(password)"Enter your Telegram two-step verification password."else"Check Telegram for your login code.").setView(entry).setNegativeButton("Later",null).setPositiveButton("Continue"){_,_->val value=entry.text.toString();entry.setText("");runWork{request("/api/telegram/answer","POST",JSONObject().put("value",value));kotlinx.coroutines.delay(700);waitTelegram()}}.show();return}
            "connected"->{showSettings();return}
            "error"->error(result.optString("error","Telegram sign-in failed"))
            "idle"->return
        };kotlinx.coroutines.delay(500)}
        Toast.makeText(this,"Sign-in is still running. Tap Continue Telegram sign-in shortly.",Toast.LENGTH_LONG).show()
    }
    private fun open(item:JSONObject,returnTo:()->Unit){page(item.optString("name","Attachment"),"Downloading and verifying…",returnTo);val g=generation;runWork{val progress=text("Checking local copy…",14f).apply{setPadding(dp(20),dp(12),dp(20),dp(12))};body.addView(progress);val progressBar=ProgressBar(this@MainActivity,null,android.R.attr.progressBarStyleHorizontal).apply{max=100;isIndeterminate=true};body.addView(progressBar);val file=withContext(Dispatchers.IO){MediaCache(this@MainActivity).use{it.ensure(item){bytes,total->runOnUiThread{if(g==generation){progress.text="Downloading: ${formatSize(bytes)} / ${formatSize(total)}";progressBar.isIndeterminate=total<=0;if(total>0)progressBar.progress=(bytes*100/total).toInt().coerceIn(0,100)}}}}};if(g!=generation)return@runWork;body.removeView(progress);body.removeView(progressBar);subtitle.text=if(cloudSaved(item))"Verified Telegram backup · available on phone"else"On this phone · Telegram backup pending";val mime=item.optString("mime");when{
        mime.startsWith("image/")->body.addView(ImageView(this@MainActivity).apply{adjustViewBounds=true;setImageBitmap(withContext(Dispatchers.IO){val o=BitmapFactory.Options().apply{inJustDecodeBounds=true};BitmapFactory.decodeFile(file.path,o);o.inSampleSize=maxOf(1,maxOf(o.outWidth,o.outHeight)/2000);o.inJustDecodeBounds=false;BitmapFactory.decodeFile(file.path,o)})},LinearLayout.LayoutParams(-1,-2))
        mime.startsWith("video/")||mime.startsWith("audio/")-> {val v=MediaPlayerView(this@MainActivity,file);currentMedia=v;body.addView(v,LinearLayout.LayoutParams(-1,dp(if(mime.startsWith("audio/"))180 else 340)))}
        mime=="application/pdf"||file.extension.equals("pdf",true)->showPdf(file,0)
        mime.startsWith("text/")->body.addView(text(withContext(Dispatchers.IO){file.inputStream().bufferedReader().use{reader->val chars=CharArray(200000);val n=reader.read(chars);if(n>0)String(chars,0,n)else ""}}))
        else->card().addView(text("The file is downloaded and verified. A built-in preview for this format is not available in this version. It remains in Whatsgramy's separate folder."))
    }}}
    private fun showPdf(file:File,index:Int){val holder=card();holder.addView(text("Rendering PDF…"));val g=generation;runWork{val result=withContext(Dispatchers.IO){ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY).use{fd->PdfRenderer(fd).use{renderer->renderer.openPage(index.coerceIn(0,renderer.pageCount-1)).use{p->val w=minOf(1600,maxOf(600,resources.displayMetrics.widthPixels));val bitmap=Bitmap.createBitmap(w,(w.toFloat()*p.height/p.width).toInt().coerceAtLeast(1),Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);p.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);bitmap to renderer.pageCount}}}};if(g!=generation){result.first.recycle();return@runWork};holder.removeAllViews();holder.addView(text("Page ${index+1} of ${result.second}",14f,true));holder.addView(ImageView(this@MainActivity).apply{adjustViewBounds=true;setImageBitmap(result.first)},LinearLayout.LayoutParams(-1,-2));val controls=LinearLayout(this@MainActivity);if(index>0)controls.addView(button("Previous"){body.removeView(holder);showPdf(file,index-1)});if(index+1<result.second)controls.addView(button("Next"){body.removeView(holder);showPdf(file,index+1)});holder.addView(controls)}}
}
class MediaPlayerView(context:Context,file:File):FrameLayout(context){private val video=VideoView(context);init{addView(video,LayoutParams(-1,-1));val controller=MediaController(context);controller.setAnchorView(video);video.setMediaController(controller);video.setVideoPath(file.path);video.setOnPreparedListener{video.start()};video.setOnErrorListener{_,_,_->Toast.makeText(context,"This device cannot decode the media format",Toast.LENGTH_LONG).show();true}};fun stop(){video.stopPlayback()}}
